<div class="pagination" x-show="pagination.total > 0"><span x-text="`${pagination.from || 0}–${pagination.to || 0} dari ${pagination.total} data`"></span><div class="button-row"><button type="button" class="btn btn-small" :disabled="pagination.current_page <= 1 || loading" @click="load(pagination.current_page - 1)">Sebelumnya</button><button type="button" class="btn btn-small" :disabled="pagination.current_page >= pagination.last_page || loading" @click="load(pagination.current_page + 1)">Berikutnya</button></div></div>
